import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mk2 import *

page(dict(
 slug='war',
 title=T('아무도 원하지 않는데 왜 전쟁이 날까?', 'Nobody Wants It, So Why Does War Happen?'),
 title_tag=T('전쟁은 어떻게 일어나고 번질까 · 시뮬라티오 랩', 'How Does War Start and Spread? · Simulatio Lab'),
 desc=T('전쟁은 양쪽 모두 손해라서 합의하는 편이 낫습니다. 그런데도 왜 일어날까요? 협상이 깨지는 일, 서로 군비를 늘리는 일, 이웃으로 번지는 일을 이름 없는 가상의 나라들로 직접 돌려 보세요.',
        'War costs both sides, so a deal should be better. Why does it still happen? Run it yourself with nameless, made-up states: talks that break down, arms races, and war spreading to neighbors.'),
 lead=T('전쟁은 늘 누군가가 원해서 일어난다고 생각하기 쉽습니다. 그런데 전쟁은 양쪽 모두에게 비싸서, 싸우지 않고 나누는 편이 둘 다에게 낫다는 합의가 언제나 존재합니다. 이 단순한 모델에서는 합의 범위가 분명히 있는데도, 상대 힘을 정확히 모른다는 이유만으로 분쟁의 약 40%가 전쟁이 됩니다. 이름 없는 추상 국가들로 돌려 보며 이 구조를 만져 보세요.',
        'It is easy to think war happens because someone wants it. But war is costly for both sides, so a deal that beats fighting always exists. In this simple model, even with such a deal clearly available, about 40% of disputes become war just because one side cannot tell how strong the other really is. Play with that structure using nameless, abstract states.'),
 model=[T('<b>① 협상 실패.</b> 두 나라(A, B)가 파이 1을 나눕니다. 전쟁을 하면 A는 이길 가능성 p만큼 얻고 양쪽 모두 비용 c를 치릅니다(A의 전쟁 몫 p−c, B의 전쟁 몫 1−p−c). 그래서 A의 몫이 p−c와 p+c 사이인 합의는 둘 다 전쟁보다 낫습니다. 다만 p는 B만 정확히 알고, A는 50%±(불확실성) 사이 어딘가라고만 짐작합니다. A는 기대 몫이 가장 큰 요구를 한 번 내밀고, B는 그 요구가 전쟁보다 나쁘면 거절해 전쟁이 납니다.',
          '<b>① Failed bargaining.</b> Two states (A, B) split a pie of size 1. In war, A gets its chance of winning p and both pay a cost c (A\'s war share is p−c, B\'s is 1−p−c). So any deal giving A between p−c and p+c beats war for both. But only B knows p exactly; A just guesses it lies within 50% ± (uncertainty). A makes one demand that maximizes its expected share, and B rejects it if war is better for B, which means war.'),
        T('<b>② 군비 경쟁.</b> 두 나라가 매 라운드 상대의 군비에 <b>반응</b>(k)해 자기 군비를 늘리고, 자기 군비의 부담에 <b>피로</b>(a)를 느껴 줄입니다. 반응이 피로보다 작으면 군비가 한 수준에서 멈추고, 크면 서로를 키우며 계속 올라갑니다. 군비가 과열선(이 프로젝트가 정한 기준)을 넘는 라운드를 셉니다.',
          '<b>② Arms race.</b> Each round, two states <b>react</b> (k) to the other\'s arms by building up, and feel the <b>fatigue</b> (a) of their own burden by cutting back. If reaction is smaller than fatigue, arms settle at some level; if larger, they keep pushing each other up. The page counts the round when arms cross a "heat line" (a threshold set by this project).'),
        T('<b>③ 번짐.</b> 15×15 격자 위의 225개 추상 국가 중 한 곳에서 전쟁이 시작됩니다. 전쟁 중인 나라는 이웃(위아래 좌우) 각각을 확률 q로 끌어들이고, 새로 끌려든 나라도 같은 방식으로 이웃을 끌어들입니다. 더 번질 곳이 없으면 그 전쟁은 끝나고, 잠시 뒤 다른 곳에서 새 전쟁이 시작됩니다. 이 단계는 번짐의 구조만 보여 주는 작은 한 단계입니다.',
          '<b>③ Spreading.</b> A war starts in one of 225 abstract states on a 15×15 grid. A state at war pulls in each neighbor (up, down, left, right) with probability q, and newly pulled-in states do the same. When nothing more can spread, that war ends, and after a short pause a new one starts elsewhere. This is a small step that only shows the structure of spreading.')],
 sliders=[('u', T('상대 힘을 잘 모르는 정도', 'How unsure we are of the other\'s strength'), 0, 0.5, 0.01, 0.25, T('A가 짐작하는 B의 힘 범위의 절반 폭. 0이면 서로 다 압니다 (① 협상)', 'Half-width of A\'s guess about the other\'s strength. At 0 everyone knows everything (① bargaining)')),
          ('c', T('전쟁의 비용', 'Cost of war'), 0.02, 0.3, 0.01, 0.15, T('전쟁이 나면 양쪽 모두 치르는 비용(파이 대비). 클수록 합의 여지가 넓지만 정보 문제는 그대로입니다 (① 협상)', 'The cost each side pays in war (relative to the pie). Larger means more room for a deal, but the information problem stays (① bargaining)')),
          ('k', T('상대 군비를 따라 늘리는 정도', 'How much we build up in response to the other\'s arms'), 0.1, 1, 0.05, 0.6, T('상대 군비 1이 늘 때 내 군비를 늘리는 정도 (② 군비 경쟁)', 'How much I build up per unit of the other\'s arms (② arms race)')),
          ('a', T('내 군비 부담을 줄이려는 정도', 'How much we want to cut our own arms burden'), 0.1, 1, 0.05, 0.45, T('내 군비가 클수록 스스로 줄이려는 정도 (② 군비 경쟁)', 'How much I cut back the larger my own arms are (② arms race)')),
          ('q', T('이웃을 끌어들일 확률', 'Chance of pulling in a neighbor'), 0, 1, 0.05, 0.5, T('전쟁 중인 나라가 이웃 한 곳을 참전시킬 확률 (③ 번짐)', 'Chance that a state at war pulls in one neighbor (③ spreading)'))],
 reroll=T('같은 설정, 다른 분쟁들', 'Same settings, different disputes'),
 sections=[
  dict(title=T('① 합의가 있었는데도 전쟁이 나는 분쟁들', '① Disputes That End in War Despite a Deal Existing'),
       p=T('점 하나가 분쟁 하나이고, 가로 위치는 A가 실제로 이길 가능성입니다(B는 알고 A는 모릅니다). A는 점선보다 오른쪽이라면 요구를 받아들여질 거라 보고 요구하는데, 실제 힘이 점선보다 왼쪽인 분쟁은 요구가 거절되어 전쟁(빨강)이 됩니다. 아래 막대는 가장 최근 분쟁에서 양쪽이 전쟁보다 나은 합의 범위(초록 띠)와 A의 요구를 보여 줍니다.',
           'Each dot is one dispute, positioned by A\'s true chance of winning (B knows it, A does not). A makes its demand expecting it to be accepted unless the true strength falls left of the dashed line; those disputes have the demand rejected and become war (red). The bar below shows, for the latest dispute, the deals both sides prefer to war (green band) and A\'s demand.'),
       id='c-bar', rounded=True, anim=True, thumb=True,
       speeds=[('3', T('느리게', 'Slow')), ('8', T('보통', 'Normal')), ('20', T('빠르게', 'Fast'))], speed_default='8'),
  dict(title=T('② 불확실성이 커질수록 전쟁이 늘어난다', '② More Uncertainty, More War'),
       p=T('가로는 불확실성, 세로는 전쟁이 되는 분쟁의 비율입니다. 빨간 선은 이 모델의 이론값(1−c/u), 초록 점은 시뮬레이션입니다. 불확실성이 전쟁 비용보다 작으면 전쟁이 한 건도 없다가, 그것을 넘으면서 늘어납니다.',
           'The horizontal axis is uncertainty and the vertical axis the share of disputes that become war. The red line is the model\'s theory (1−c/u) and the green dots are simulations. Below the cost of war there is no war at all, and above it war grows.'),
       id='c-u'),
  dict(title=T('③ 군비 경쟁: 멈출까, 폭주할까', '③ Arms Race: Will It Settle or Run Away?'),
       p=T('파랑과 보라는 두 나라의 군비 수준입니다. 반응(k)이 피로(a)보다 작으면 두 선이 한 수준에서 멈추고(초록 점선), 크면 서로를 끌어올려 빨간 과열선을 넘습니다. 슬라이더로 k와 a를 가까이 붙여 보세요.',
           'Blue and purple are the two states\' arms levels. When reaction (k) is below fatigue (a) both lines settle at one level (green dotted), and when above they pull each other past the red heat line. Try moving k and a close together with the sliders.'),
       id='c-arms'),
  dict(title=T('④ 한 나라의 전쟁이 이웃으로 번지는 모습', '④ How One War Spreads to Neighbors'),
       p=T('격자 한 칸이 한 나라입니다. 테두리 친 칸에서 시작해 진한 빨강에서 옅은 주황 순서로 끌려든 나라를 칠합니다. 오른쪽(휴대폰에서는 아래) 막대는 끝난 전쟁마다 참전한 나라 수입니다.',
           'Each cell is one state. The war starts in the outlined cell, and states pulled in are painted from deep red to pale orange in order. The bars on the right (below, on phones) show how many states joined each finished war.'),
       id='c-grid'),
  dict(title=T('⑤ 번질 확률이 어느 선을 넘으면', '⑤ When the Spreading Chance Passes a Tipping Line'),
       p=T('가로는 이웃을 끌어들일 확률, 파란 선은 평균 참전국 비율, 빨간 선은 전체의 25% 이상으로 번진 전쟁의 비율입니다(확률마다 300번씩 시뮬레이션). 정사각 격자에서는 이 확률이 50% 근처에서 갑자기 큰 번짐이 가능해집니다.',
           'The horizontal axis is the chance of pulling in a neighbor, the blue line the average share of states joining, and the red line the share of wars that spread to 25% or more of all states (300 simulations per value). On a square grid, big spreads suddenly become possible near 50%.'),
       id='c-q'),
 ],
 says=T('① 전쟁 비용 15%, 불확실성 ±25%에서 A는 자기 몫을 가장 크게 기대하는 요구(60%)를 했고, 이론상 분쟁의 40.0%가 전쟁이 됩니다(시뮬레이션 20만 건에서 39.8%). 양쪽이 전쟁보다 낫다고 여길 합의 범위(폭 30%)가 늘 있었는데도 그렇습니다. 정보가 정확하면(불확실성 0) 전쟁은 0%였고, 불확실성이 15% 이하이면 전쟁 비용과 같거나 작아 역시 0%였습니다. 불확실성 20%에서 25.0%, 30%에서 50.0%, 40%에서 62.5%, 50%에서 70.0%로 늘었습니다. 불확실성 ±25%에서 전쟁 비용을 5%로 낮추면 80.0%, 10%는 60.0%, 20%는 20.0%였고 25% 이상에서는 0%였습니다. 두 방법으로 45개 조합을 비교했을 때 이론과 시뮬레이션의 차이는 최대 0.1%p였습니다. ② 군비 경쟁은 반응 k가 피로 a보다 작으면 멈추고 클수록 폭주했습니다(k, a를 0.1~1.0으로 바꾼 342개 조합이 모두 이 조건과 일치). 기본값(k 0.60, a 0.45)에서는 모든 시드(1~5)에서 31라운드에 과열선에 닿았고, k 0.50 · a 0.45에서는 63~64라운드로 늦어졌습니다. k 0.50 · a 0.60이면 이론상 안정 수준 1.00에 시뮬레이션 평균 0.99로 멈췄습니다. ③ 이웃을 끌어들일 확률이 30%일 때 평균 참전 5.5개국(2.5%), 40%에서 17.1개국, 50%에서 69.9개국(31.1%), 60%에서 169.7개국(75.4%), 70%에서 213.0개국(94.7%)이었습니다. 50%에서는 전쟁의 49.6%가 전체의 25% 이상으로 번졌고, 같은 설정에서 규모가 1~2개국에 그친 전쟁도 12.5%였습니다. 30%에서는 가장 큰 전쟁도 57개국(2만 번 중)이었습니다.',
        '① With a war cost of 15% and uncertainty of ±25%, A makes the demand with the best expected share (60%), and in theory 40.0% of disputes become war (39.8% in 200,000 simulated disputes), even though a range of deals (30% wide) that both sides prefer to war always existed. With accurate information (uncertainty 0) war was 0%, and with uncertainty at or below 15%, no larger than the war cost, it was 0% too. It grew to 25.0% at uncertainty 20%, 50.0% at 30%, 62.5% at 40% and 70.0% at 50%. At uncertainty ±25%, a war cost of 5% gave 80.0%, 10% gave 60.0%, 20% gave 20.0%, and from 25% on it was 0%. Across 45 combinations, theory and simulation differed by at most 0.1 percentage points. ② In the arms race, arms settled when reaction k was below fatigue a and ran away otherwise (all 342 combinations of k and a from 0.1 to 1.0 matched that condition). With the defaults (k 0.60, a 0.45) every seed (1 to 5) hit the heat line at round 31, and with k 0.50 and a 0.45 it was delayed to rounds 63 to 64. With k 0.50 and a 0.60 arms settled at the theoretical level of 1.00, averaging 0.99 in simulation. ③ With a 30% chance of pulling in a neighbor, an average of 5.5 states (2.5%) joined; 17.1 at 40%, 69.9 (31.1%) at 50%, 169.7 (75.4%) at 60%, and 213.0 (94.7%) at 70%. At 50%, 49.6% of wars spread to 25% or more of all states, yet 12.5% stayed within 1 or 2 states. At 30% even the largest war (out of 20,000) had 57 states.'),
 **{'not': T('실제 전쟁의 원인을 설명하거나 예측하지 않습니다. 실제 전쟁은 훨씬 복잡합니다. 이 페이지의 나라들은 이름도 얼굴도 없는 추상 국가이며, 어떤 실제 분쟁도 가리키지 않습니다. 세 모델은 모두 이 프로젝트가 크게 단순화한 것입니다. 전쟁의 이득과 비용을 파이의 몫으로만 다루고, 사람의 고통이나 국내 정치, 이념, 동맹, 제3자의 개입은 담지 않았습니다. 이 결과는 "이런 구조가 전쟁을 만들 수 있다"는 가능성을 보여 줄 뿐, 어느 전쟁이 이렇게 일어났다는 증거가 아닙니다. 또 협상 실패에는 정보 문제 외에 약속을 믿지 못하는 문제 등도 있는데 여기서는 다루지 않았습니다. 군비 경쟁의 과열선과 번짐 격자의 크기, 번짐 확률은 이 프로젝트가 정한 값이고, 군비가 많다고 곧 전쟁이 난다는 뜻도 아닙니다.',
                'This does not explain or predict the causes of real wars. Real wars are far more complex. The states on this page are nameless, faceless abstractions and point to no real conflict. All three models are heavy simplifications by this project: gains and costs of war are only shares of a pie, and human suffering, domestic politics, ideology, alliances and third-party intervention are left out. The results only show that such structures can produce war; they are no evidence that any particular war began this way. Bargaining can also fail for reasons beyond information, such as an inability to trust promises, which is not covered here. The heat line for arms, the size of the grid and the spreading chances are values chosen by this project, and having many arms does not mean war will break out.')},
 theory=[
  ('root', T("세 부분은 각각 다른 고전에서 왔습니다. 협상 부분은 James Fearon의 1995년 논문 「Rationalist Explanations for War」(<i>International Organization</i>)로, 전쟁이 비싸서 늘 더 나은 합의가 있는데도 정보 비대칭 같은 이유로 협상이 깨질 수 있다는 설명입니다. 군비 경쟁 부분은 Lewis Fry Richardson의 『Arms and Insecurity』(1960)에서 나온 상호 반응 모델입니다. 번짐 부분은 격자 위 확률적 전파(결합 퍼콜레이션) 모델이고, 전쟁의 규모 통계를 다룬 Richardson의 『Statistics of Deadly Quarrels』(1960)가 배경입니다.",
         "The three parts come from different classics. The bargaining part follows James Fearon's 1995 paper &quot;Rationalist Explanations for War&quot; (<i>International Organization</i>): war is costly so a better deal always exists, yet bargaining can fail because of reasons such as asymmetric information. The arms race part is the mutual-reaction model from Lewis Fry Richardson's <i>Arms and Insecurity</i> (1960). The spreading part is a probabilistic spread on a grid (bond percolation), with Richardson's <i>Statistics of Deadly Quarrels</i> (1960), on the statistics of war sizes, as its background.")),
  ('model', T("① A의 승리 가능성 p는 [0.5−u, 0.5+u]에서 고르게 나오고, 전쟁 때 A는 p−c, B는 1−p−c를 얻으므로 A의 몫이 p−c와 p+c 사이인 합의가 둘 다에게 낫습니다. A가 요구 x를 하면 B는 p ≥ x−c일 때 받아들입니다. A의 기대 몫을 최대화하면 문턱은 p = 0.5+u−2c이고, 그 아래의 분쟁이 전쟁이 되어 전쟁 확률은 <code>max(0, 1 − c/u)</code>입니다. ② 군비 <code>x' = x + dt(k·y − a·x + g)</code>, y도 대칭(dt = 0.5, g = 0.1)이고 약간의 잡음이 섞입니다. 이 대칭 경우 <code>k &lt; a</code>이면 안정 수준 <code>g/(a−k)</code>에 닿고 아니면 무한히 커집니다(일반형은 k₁k₂ &lt; a₁a₂). ③ 격자 위 각 연결이 확률 q로 열려 한 나라에서 퍼지는 군집이 전쟁의 규모이고, 정사각 격자의 임계값은 1/2입니다. 슬라이더는 u, c(①), k, a(②), q(③)입니다.",
         "① A's winning chance p is uniform on [0.5−u, 0.5+u]. In war A gets p−c and B gets 1−p−c, so any deal giving A between p−c and p+c is better for both. If A demands x, B accepts when p ≥ x−c. Maximizing A's expected share gives a threshold at p = 0.5+u−2c; disputes below it become war, so the war probability is <code>max(0, 1 − c/u)</code>. ② Arms follow <code>x' = x + dt(k·y − a·x + g)</code>, with y symmetric (dt = 0.5, g = 0.1) and a little noise. In this symmetric case, if <code>k &lt; a</code> arms settle at <code>g/(a−k)</code>, otherwise they grow without limit (in general k₁k₂ &lt; a₁a₂). ③ Each link on the grid is open with probability q, and the cluster reached from one state is the war's size; the threshold for a square grid is 1/2. The sliders are u and c (①), k and a (②), and q (③).")),
  ('simplify', T("현실의 전쟁에는 비용의 크기가 사람마다 다르고, 지도자와 국내 사정, 동맹, 약속의 신뢰 문제 등이 얽힙니다. 이 프로젝트는 비용을 양쪽 같은 c로, 힘의 불확실성을 고른 분포로, A가 한 번만 요구하는 방식으로 줄였습니다. 군비 경쟁은 두 나라가 똑같은 대칭 모델이고 과열선(10)과 자극값(g = 0.1)은 이 프로젝트가 정했습니다. 번짐은 15×15 격자, 위아래 좌우 이웃만, 모든 연결이 같은 확률인 단순화이며 동맹 같은 구조는 없습니다(동맹의 연쇄는 별도 실험 참고).",
         "Real wars involve costs that differ by actor, leaders, domestic circumstances, alliances and problems of trusting promises. This project reduces it to the same cost c for both sides, a uniform distribution for uncertainty about strength, and a single demand from A. The arms race is a symmetric model with identical states, and the heat line (10) and the constant pressure (g = 0.1) are this project's own values. Spreading is a 15×15 grid with only four neighbors and the same probability on every link, with no alliances (see the separate alliance experiment for chains of alliances).")),
  ('check', T("① 전쟁 확률 <code>max(0, 1−c/u)</code>를 시뮬레이션과 비교했을 때 기본값에서 이론 40.0%, 20만 건 시뮬레이션 39.8%였고, u 0~0.5, c 0.05~0.3의 45개 조합에서 최대 차이는 0.1%p였습니다. ② 안정 조건 k &lt; a는 342개 k, a 조합이 모두 일치했고(경계 k = a는 제외), 안정 수준은 k 0.5 · a 0.6에서 이론 1.00, 시뮬레이션 0.99였습니다. ③ 임계점 1/2는 격자에서 한 나라가 시작한 전쟁의 평균 참전국이 q 0.3에서 5.5개국, 0.5에서 69.9개국, 0.7에서 213.0개국으로 급증하는 것과 맞았습니다. 다만 15×15의 유한한 격자라서 50% 부근이 매끈하게 번지고, 정확한 임계값 1/2는 무한 격자의 값입니다.",
         "① Comparing the war probability <code>max(0, 1−c/u)</code> with simulation, the defaults gave a theory of 40.0% and 39.8% in 200,000 simulated disputes; across 45 combinations of u from 0 to 0.5 and c from 0.05 to 0.3 the largest gap was 0.1 percentage points. ② The stability condition k &lt; a matched in all 342 combinations of k and a (excluding the boundary k = a), and the settled level at k 0.5 and a 0.6 was 1.00 in theory and 0.99 in simulation. ③ The threshold of 1/2 agreed with the average number of states in a war started in one state on the grid jumping from 5.5 at q 0.3 to 69.9 at 0.5 and 213.0 at 0.7. Because the 15×15 grid is finite the rise around 50% is smoothed, and the exact threshold of 1/2 is the value for an infinite grid.")),
  ('read', T("Fearon (1995), &quot;Rationalist Explanations for War&quot;, <i>International Organization</i> / Richardson (1960), <i>Arms and Insecurity</i>, Boxwood Press / Richardson (1960), <i>Statistics of Deadly Quarrels</i>, Boxwood Press.",
         "Fearon (1995), &quot;Rationalist Explanations for War&quot;, <i>International Organization</i> / Richardson (1960), <i>Arms and Insecurity</i>, Boxwood Press / Richardson (1960), <i>Statistics of Deadly Quarrels</i>, Boxwood Press.")),
 ],
 memo=[T('검증은 <code>node tools/validate-war.js</code>로 할 수 있습니다. 시뮬레이션은 시드 난수(mulberry32)를 쓰고 같은 시드면 같은 결과가 나옵니다. 화면의 분쟁은 한 라운드에 4건씩 쌓이고, 번짐은 한 라운드에 한 겹씩 퍼집니다.',
         'You can verify with <code>node tools/validate-war.js</code>. The simulation uses a seeded random generator (mulberry32), so the same seed gives the same result. On screen, four disputes are added per round and a war spreads one layer per round.')],
))
